    {var menu=new MenuButton {Text=text};parent.AddChild(menu);foreach(string entry in entries)menu.GetPopup().AddItem(entry);menu.GetPopup().IdPressed+=index=>select(index);return menu;}
    private static void Clipboard(Control owner,Resource? document)
    {if(document!=null)owner.GetTree().Root.GetNodeOrNull<Node>("SuperClipboard")?.Call("quick_save",document,document.Get("title"),"default");}
